// Created: 2026-11-02

import { spawn } from 'node:child_process';
import { copyFileSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

// The shipped hooks.json runs every PreToolUse guard through
// pretool/tool-dispatcher and every PostToolUse guard through
// posttool/tool-dispatcher. Before they shipped, the guards they fold in
// (sync-bash-dispatcher, sync-write-edit-dispatcher, skill/redact-secrets)
// were each in SECURITY_HOOKS, so:
//   1. a bundle that exists but fails to import blocked (exit 2), and
//   2. a user-scope hook-overrides.json could not disable them.
// The dispatchers must keep both properties, or making them the default
// opens two fail-open paths the per-handler hooks.json did not have.

const BIN_DIR = join(__dirname, '../../../bin');
const RUNNER_FILES = ['run-hook.mjs', 'output-guard.mjs', 'analytics-rotate.mjs', 'cc-output-keys.generated.mjs'];
const DISPATCHERS = [
  { hook: 'pretool/tool-dispatcher', bundle: 'pretool', event: 'PreToolUse' },
  { hook: 'posttool/tool-dispatcher', bundle: 'posttool', event: 'PostToolUse' },
] as const;

let root: string;
let home: string;
let runner: string;

beforeEach(() => {
  root = mkdtempSync(join(tmpdir(), 'dispatcher-security.'));
  home = join(root, 'home');
  mkdirSync(join(root, 'hooks', 'bin'), { recursive: true });
  mkdirSync(join(root, 'hooks', 'dist'), { recursive: true });
  mkdirSync(join(home, '.claude'), { recursive: true });
  for (const f of RUNNER_FILES) copyFileSync(join(BIN_DIR, f), join(root, 'hooks', 'bin', f));
  runner = join(root, 'hooks', 'bin', 'run-hook.mjs');
});

afterEach(() => {
  rmSync(root, { recursive: true, force: true });
});

function run(hook: string, event: string): Promise<{ code: number | null; stdout: string; stderr: string }> {
  return new Promise((resolve) => {
    const child = spawn('node', [runner, hook], {
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env, HOME: home, USERPROFILE: home, CLAUDE_PROJECT_DIR: root },
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (c) => { stdout += String(c); });
    child.stderr.on('data', (c) => { stderr += String(c); });
    child.on('close', (code) => resolve({ code, stdout, stderr }));
    child.stdin.on('error', () => {});
    child.stdin.end(JSON.stringify({
      hook_event_name: event,
      session_id: '00000000-0000-4000-8000-000000000000',
      cwd: '/tmp',
      tool_name: 'Bash',
      tool_input: { command: 'echo hi' },
      tool_response: { stdout: 'hi', stderr: '', interrupted: false },
    }));
  });
}

describe('tool dispatchers keep the SECURITY_HOOKS guarantees of the guards they fold in', () => {
  for (const d of DISPATCHERS) {
    it(`${d.hook}: a bundle that exists but fails to import blocks (exit 2), not a non-blocking exit 1`, async () => {
      writeFileSync(join(root, 'hooks', 'dist', `${d.bundle}.mjs`), 'export const hooks = {\n', 'utf8');
      const r = await run(d.hook, d.event);
      expect(r.code).toBe(2);
      expect(r.stderr).toContain(`hook "${d.hook}" bundle at`);
    }, 20000);

    it(`${d.hook}: a user-scope hook-overrides.json cannot disable it`, async () => {
      // A loadable bundle whose dispatcher blocks: if the override were honored,
      // the runner would print a silent continue and the block would be lost.
      writeFileSync(
        join(root, 'hooks', 'dist', `${d.bundle}.mjs`),
        `export const hooks = { '${d.hook}': () => ({ continue: false, stopReason: 'probe block' }) };\n`,
        'utf8',
      );
      writeFileSync(join(home, '.claude', 'hook-overrides.json'), JSON.stringify({ disabled: [d.hook] }), 'utf8');
      const r = await run(d.hook, d.event);
      expect(r.stderr).toContain(`cannot disable security hook "${d.hook}"`);
      expect(r.stdout).toContain('probe block');
    }, 20000);
  }
});
